import{_ as n,C as i,o as t,c as s,a2 as o,b as l,w as a,a as d,E as c,a3 as h}from"./chunks/framework.CZqXuAiL.js";const f=JSON.parse('{"title":"Webhooks & Alerts","description":"Firewall-Plus notifications — the admin Discord webhook, per-server owner Discord webhooks, and owner email alerts for SMART attacks.","frontmatter":{"title":"Webhooks & Alerts","description":"Firewall-Plus notifications — the admin Discord webhook, per-server owner Discord webhooks, and owner email alerts for SMART attacks."},"headers":[],"relativePath":"firewall-plus/fwp-aside/user-guide/webhooks.md","filePath":"firewall-plus/fwp-aside/user-guide/webhooks.md","lastUpdated":1785959583000}'),m={name:"firewall-plus/fwp-aside/user-guide/webhooks.md"};function w(g,e,b,p,v,k){const r=i("Mermaid");return t(),s("div",null,[e[1]||(e[1]=o('<h1 id="webhooks-alerts" tabindex="-1">Webhooks &amp; Alerts <a class="header-anchor" href="#webhooks-alerts" aria-label="Permalink to &quot;Webhooks &amp; Alerts&quot;">​</a></h1><p>Firewall-Plus notifies through three channels, each with a different audience:</p><table tabindex="0"><thead><tr><th>Channel</th><th>Audience</th><th>Configured at</th><th>Covers</th></tr></thead><tbody><tr><td>Admin Discord webhook</td><td>Host operators</td><td>Admin → Firewall → Settings → <code>webhook_url</code></td><td>Fleet events: node incidents, applies, SMART attacks</td></tr><tr><td>Owner Discord webhook</td><td>Individual server owner</td><td>Server → Firewall → SMART tab</td><td>That server&#39;s SMART attack events</td></tr><tr><td>Owner email</td><td>Individual server owner</td><td>Admin setting <code>smart_owner_email_enabled</code> (master switch)</td><td>That server&#39;s SMART attack events</td></tr></tbody></table><hr><h2 id="admin-discord-webhook" tabindex="-1">Admin Discord Webhook <a class="header-anchor" href="#admin-discord-webhook" aria-label="Permalink to &quot;Admin Discord Webhook&quot;">​</a></h2><ol><li>In Discord: channel → <strong>Edit Channel → Integrations → Webhooks → New Webhook</strong>, copy the URL.</li><li>Panel: <strong>Admin → Firewall → Settings</strong> → paste into <strong>Webhook URL</strong> and save.</li></ol><p>The panel sends rich Discord embeds (<code>FirewallWebhookService</code>) for operational events — node offline/online transitions, apply failures, and SMART attack events synced from nodes.</p><div class="tip custom-block"><p class="custom-block-title">Controlling alert volume</p><p><code>node_offline_webhook_max</code> (settings) caps how many offline notifications one flapping node can generate per incident. SMART events sync from nodes every 2 minutes via <code>SyncSmartEventsJob</code>.</p></div><hr><h2 id="per-server-owner-discord-webhook" tabindex="-1">Per-Server Owner Discord Webhook <a class="header-anchor" href="#per-server-owner-discord-webhook" aria-label="Permalink to &quot;Per-Server Owner Discord Webhook&quot;">​</a></h2><p>Server owners can get their own attack alerts without involving the host:</p><ol><li>Owner creates a webhook in their own Discord server (same steps as above).</li><li>Server → <strong>Firewall → SMART tab</strong> → paste the webhook URL → save. <ul><li>API equivalent: <code>PUT /api/client/servers/{server}/v1/firewall/smart/webhook</code></li></ul></li><li>Requires SMART mode granted by an admin and enabled on the server.</li></ol><p>When the node&#39;s SMART engine raises an attack event for that server, the owner webhook fires with the detection details (level, metrics vs. baseline, mitigation applied).</p><h2 id="owner-email-alerts" tabindex="-1">Owner Email Alerts <a class="header-anchor" href="#owner-email-alerts" aria-label="Permalink to &quot;Owner Email Alerts&quot;">​</a></h2><p>Email alerts use the panel&#39;s mailer — no extra credentials needed beyond working panel mail.</p><ol><li>Admin → <strong>Firewall → Settings</strong> → enable <strong><code>smart_owner_email_enabled</code></strong>.</li><li>That&#39;s it: every SMART attack event emails the <strong>server owner</strong> via a dedicated mailable.</li></ol><p>This is a fleet-wide master switch — when off, owners get Discord-only notifications. Owners don&#39;t configure anything themselves; the alert goes to their panel account email.</p><hr><h2 id="acknowledging-events" tabindex="-1">Acknowledging Events <a class="header-anchor" href="#acknowledging-events" aria-label="Permalink to &quot;Acknowledging Events&quot;">​</a></h2><p>Attack events stay &quot;unacknowledged&quot; until someone marks them seen — useful for shared-server teams and for hosts tracking response:</p><ul><li><strong>Client UI:</strong> server → Firewall → Logs / SMART tab → acknowledge (<code>POST /api/client/servers/{server}/v1/firewall/smart/events/{id}/ack</code>)</li><li><strong>Admin UI:</strong> <strong>Admin → Firewall → Activity</strong> → SMART events section → acknowledge</li></ul><p>While a mitigation is active, the admin <strong>Servers index</strong> shows an <strong>&quot;under mitigation&quot;</strong> badge on that server&#39;s row, so ongoing attacks are visible at a glance across the fleet.</p><h2 id="event-lifecycle" tabindex="-1">Event Lifecycle <a class="header-anchor" href="#event-lifecycle" aria-label="Permalink to &quot;Event Lifecycle&quot;">​</a></h2>',23)),(t(),l(h,null,{default:a(()=>[c(r,{id:"mermaid-172",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20N%20as%20Node%20(SMART%20monitor)%0A%20%20%20%20participant%20P%20as%20Panel%0A%20%20%20%20participant%20D%20as%20Discord%20(admin%20%2B%20owner)%0A%20%20%20%20participant%20M%20as%20Email%20(owner)%0A%20%20%20%20N-%3E%3EN%3A%20EWMA%20anomaly%20%E2%86%92%20L1-L3%20mitigation%0A%20%20%20%20N-%3E%3EP%3A%20Event%20pulled%20by%20SyncSmartEventsJob%20(2%20min)%0A%20%20%20%20P-%3E%3EP%3A%20Store%20in%20firewall_smart_events%20%2B%20audit%0A%20%20%20%20P-%3E%3ED%3A%20Discord%20embeds%20(admin%20webhook%2C%20owner%20webhook)%0A%20%20%20%20P-%3E%3EM%3A%20Owner%20email%20(if%20smart_owner_email_enabled)%0A%20%20%20%20Note%20over%20P%3A%20Event%20visible%20in%20client%20Logs%20%2B%20admin%20Activity%3Cbr%2F%3Euntil%20acknowledged%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>No Discord messages:</strong> verify the URL still exists in Discord (deleted webhooks fail silently), and check <code>storage/logs/laravel.log</code> for webhook errors.</li><li><strong>No owner emails:</strong> confirm <code>smart_owner_email_enabled</code> is on <strong>and</strong> panel mail works generally (<code>php artisan tinker</code> → send a test, or check your mail driver logs). The toggle only gates SMART alerts; it doesn&#39;t fix broken panel mail.</li><li><strong>Duplicate-feeling alerts:</strong> an event fires once per detection, but each L1→L3 escalation is a separate event. That&#39;s intentional — escalation is new information.</li></ul>',2))])}const A=n(m,[["render",w]]);export{f as __pageData,A as default};
